  `allow_allocated_showinall` varchar(20) DEFAULT 'no' COMMENT ' 允许公海已分配客户显示在“全部（含指定公海）”列表 ',
  `allow_trasnfer_others` varchar(20) DEFAULT 'no' COMMENT ' 允许公海成员将已分配或领取的公海客户转移到其他公海 ',
