  `sequence` int(10) DEFAULT '0',
  `default_pool` varchar(20) DEFAULT NULL,
  `poolmember_show_noallocate` varchar(10) DEFAULT NULL,
  `releasetype` varchar(20) DEFAULT NULL,
  `active` varchar(20) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_account_public_pool__id` (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8;
