where_time\n							FROM\n								sequence\n							WHERE\n								YEAR (\n									DATE_ADD(\n										\'{starttime}\',\n										INTERVAL seq YEAR\n									)\n								) <= YEAR (\'{endtime}\')\n						) where_table\n					WHERE\n						date LIKE \'%2023%\'\n					GROUP BY\n						where_time,\n						group_time\n				) timetype_table\n			LEFT JOIN (\n				SELECT\n					ld_salesorder.salesorderid,\n					YEAR (ld_salesorder.signed_data) AS where_time,\n					(\n						CASE\n						WHEN \'{timetype}\' = \'月\' THEN\n							MONTH (ld_salesorder.signed_data)\n						WHEN \'{timetype}\' = \'季度\' THEN\n							QUARTER (ld_salesorder.signed_data)\n						ELSE\n							MONTH (ld_salesorder.signed_data)\n						END\n					) AS group_time,\n					sum(\n						now_s_detail.tax_amount / ld_salesorder.conversion_rate\n					) AS tax_amount\n				FROM\n					ld_salesorder\n				LEFT JOIN ld_salesorderdetail now_s_detail ON now_s_detail.id = ld_salesorder.salesorderid\n				LEFT JOIN ld_products ON ld_products.productid = now_s_detail.productid\n				WHERE\n					(\n						ld_products.productname = \'{productname}\'\n						OR \'{productname}\' = \'\'\n					)\n				AND (\n					\'{productcategory}\' = \'\'\n					OR FIND_IN_SET(\n						ld_products.productcategory,\n						\'{productcategory}\'\n					)\n				)\n				AND FIND_IN_SET(\n					ld_salesorder.approvestatus,\n					\'{approvestatus}\'\n				)\n				AND FIND_IN_SET(\n					ld_salesorder.smownerid,\n					\'{userscope}\'\n				)\n				AND (\n					ld_salesorder.signed_data BETWEEN \'{starttime}\'\n					AND \'{endtime}\'\n				)\n				GROUP BY\n					where_time,\n					group_time\n			) now_salesorder ON now_salesorder.group_time = timetype_table.group_time\n			AND now_salesorder.where_time = timetype_table.where_time\n			LEFT JOIN (\n				SELECT\n					ld_salesorder.salesorderid,\n					(\n						CASE\n						WHEN \'{timetype}\' = \'月\' THEN\n							YEAR (\n								DATE_ADD(\n									ld_salesorder.signed_data,\n									INTERVAL 1 MONTH\n								)\n							)\n						WHEN \'{timetype}\' = \'季度\' THEN\n							YEAR (\n								DATE_ADD(\n									ld_salesorder.signed_data,\n									INTERVAL 1 QUARTER\n								)\n							)\n						ELSE\n							YEAR (\n								DATE_ADD(\n									ld_salesorder.signed_data,\n									INTERVAL 1 MONTH\n								)\n							)\n						END\n					) AS where_time,\n					(\n						CASE\n						WHEN \'{timetype}\' = \'月\' THEN\n							MONTH (\n								DATE_ADD(\n									ld_salesorder.signed_data,\n									INTERVAL 1 MONTH\n								)\n							)\n						WHEN \'{timetype}\' = \'季度\' THEN\n							QUARTER (\n								DATE_ADD(\n									ld_salesorder.signed_data,\n									INTERVAL 1 QUARTER\n								)\n							)\n						ELSE\n							MONTH (\n								DATE_ADD(\n									ld_salesorder.signed_data,\n									INTERVAL 1 MONTH\n								)\n							)\n						END\n					) AS group_time,\n					sum(\n						pre_s_detail.tax_amount / ld_salesorder.conversion_rate\n					) AS tax_amount\n				FROM\n					ld_salesorder\n				LEFT JOIN ld_salesorderdetail pre_s_detail ON pre_s_detail.id = ld_salesorder.salesorderid\n				LEFT JOIN ld_products ON ld_products.productid = pre_s_detail.productid\n				WHERE\n					(\n						ld_products.productname = \'{productname}\'\n						OR \'{productname}\' = \'\'\n					)\n				AND (\n					\'{productcategory}\' = \'\'\n					OR FIND_IN_SET(\n						ld_products.productcategory,\n						\'{productcategory}\'\n					)\n				)\n				AND FIND_IN_SET(\n					ld_salesorder.approvestatus,\n					\'{approvestatus}\'\n				)\n				AND FIND_IN_SET(\n					ld_salesorder.smownerid,\n					\'{userscope}\'\n				)\n				GROUP BY\n					where_time,\n					group_time\n			) pre_salesorder ON pre_salesorder.group_time = timetype_table.group_time\n			AND pre_salesorder.where_time = timetype_table.where_time\n			GROUP BY\n				timetype_table.group_time\n		)\n		UNION ALL\n			(\n				SELECT\n					timetype_table.group_time AS group_time,\n					timetype_table.where_time AS where_time,\n					pre_servicecontracts.tax_amount AS pre_tax_amount,\n					now_servicecontracts.tax_amount AS now_tax_amount\n				FROM\n					(\n						SELECT\n							(\n								CASE\n								WHEN \'{timetype}\' = \'月\' THEN\n									MONTH (date)\n								WHEN \'{timetype}\' = \'季度\' THEN\n									QUARTER (date)\n								ELSE\n									MONTH (date)\n								END\n							) AS group_time,\n							where_table.where_time AS where_time\n						FROM\n							tmp_date,\n							(\n								SELECT\n									YEAR (\n										DATE_ADD(\n											\'{starttime}\',\n											INTERVAL seq YEAR\n										)\n									) where_time\n								FROM\n									sequence\n								WHERE\n									YEAR (\n										DATE_ADD(\n											\'{starttime}\',\n											INTERVAL seq YEAR\n										)\n									) <= YEAR (\'{endtime}\')\n							) where_table\n						WHERE\n							date LIKE \'%2023%\'\n						GROUP BY\n							where_time,\n							group_time\n					) timetype_table\n				LEFT JOIN (\n					SELECT\n						ld_servicecontracts.servicecontractsid,\n						YEAR (due_date) AS where_time,\n						(\n							CASE\n							WHEN \'{timetype}\' = \'月\' THEN\n								MONTH (due_date)\n							WHEN \'{timetype}\' = \'季度\' THEN\n								QUARTER (due_date)\n							ELSE\n								MONTH (due_date)\n							END\n						) AS group_time,\n						sum(\n							now_sv_detail.tax_amount / ld_servicecontracts.conversion_rate\n						) AS tax_amount\n					FROM\n						ld_servicecontracts\n					LEFT JOIN ld_servicecontractsdetail now_sv_detail ON now_sv_detail.id = ld_servicecontracts.servicecontractsid\n					LEFT JOIN ld_products ON ld_products.productid = now_sv_detail.productid\n					WHERE\n						(\n							ld_products.productname = \'{productname}\'\n							OR \'{productname}\' = \'\'\n						)\n					AND (\n						\'{productcategory}\' = \'\'\n						OR FIND_IN_SET(\n							ld_products.productcategory,\n							\'{productcategory}\'\n						)\n					)\n					AND FIND_IN_SET(\n						ld_servicecontracts.approvestatus,\n						\'{approvestatus}\'\n					)\n					AND FIND_IN_SET(\n						ld_servicecontracts.smownerid,\n						\'{users