d',NULL,'yes','yes','no',0,3,65,NULL,NULL),(120,'客户销售合同统计',85,'',1,'no','bottom','no','yes','2023-04-28 11:53:04','2023-04-28 11:53:04',0,1,1,0,'selectfield',NULL,'yes','yes','no',0,3,66,NULL,NULL),(121,'销售订单出库情况',87,'',4,'no','bottom','no','yes','2023-04-28 11:53:04','2023-04-28 11:53:04',0,1,1,0,'selectfield',NULL,'yes','yes','no',0,3,68,NULL,NULL),(122,'员工订单金额统计',87,'',1,'no','bottom','no','yes','2023-04-28 11:53:04','2023-04-28 11:53:04',0,1,1,0,'selectfield',NULL,'yes','yes','no',0,3,68,NULL,NULL),(123,'客户服务单汇总',90,'',3,'no','bottom','no','yes','2023-04-28 11:53:04','2023-04-28 11:53:04',0,1,1,0,'selectfield',NULL,'yes','yes','no',0,3,69,NULL,NULL),(124,'商机平均结单周期统计（按人员）',NULL,'',NULL,'no',NULL,NULL,'yes','2023-03-23 15:38:48','2023-03-23 15:55:43',0,1,1,0,'sql','select \nsmownerid,\npotential_no,\npotentialid,\npotentialname,\naccountname,\nlast_name,\ntotal,\nsales_stage,\ncreatedtime,\nchangedon,\ngaptime,\nordernum\nfrom (\nselect \np.smownerid,\np.potential_no,\np.potentialid,\np.potentialname,\na.accountname,\nu.last_name,\np.total,\np.sales_stage,\np.createdtime,\nmodtracker.changedon,\ntimestampdiff(HOUR,p.createdtime,modtracker.changedon)as gaptime,\n1 as ordernum\nfrom \nld_potential p \nleft join ld_account a on p.accountid=a.accountid\nleft join ld_users u on u.id=p.smownerid\nleft join(\nselect \nld_modtracker_basic.crmid,\nmax(ld_modtracker_basic.changedon) as changedon,\nld_modtracker_detail.fieldname,\nld_modtracker_detail.postvalue\nfrom ld_modtracker_basic \nleft join ld_modtracker_detail on ld_modtracker_basic.id=ld_modtracker_detail.id\nwhere ld_modtracker_basic.module=\'Potentials\'\nand ld_modtracker_detail.postvalue=\'成功结案\' \nand ld_modtracker_detail.fieldname=\'sales_stage\'\ngroup by ld_modtracker_basic.crmid\n)modtracker on modtracker.crmid=p.potentialid\nwhere p.sales_stage=\'成功结案\'  and p.deleted=0 \nand p.createdtime>=DATE_FORMAT(\'{starttime}\',\'%Y-%m-%d 00:00:00\') and p.createdtime<=DATE_FORMAT(\'{endtime}\',\'%Y-%m-%d 23:59:59\')\nand find_in_set(p.smownerid,\'{userid}\')\nunion all \nselect \nsmownerid,\n\'\' as potential_no,\n\'\' as potentialid,\n\'\' as potentialname,\n\'\' as accountname,\nconcat(last_name,\'-小计\') as last_name,\n\'\' as total,\n\'\' as sales_stage,\n\'\' as createdtime,\n\'\' as changedon,\nsum(timestampdiff(HOUR,createdtime,changedon))/count(1) as gaptime,\n2 as ordernum\nfrom (\nselect \np.smownerid,\np.potential_no,\np.potentialid,\np.potentialname,\nu.last_name,\np.total,\np.sales_stage,\np.createdtime,\nmodtracker.changedon,\ntimestampdiff(HOUR,p.createdtime,modtracker.changedon)as gaptime,\n2 as ordernum\nfrom \nld_potential p \nleft join ld_account a on p.accountid=a.accountid\nleft join ld_users u on u.id=p.smownerid\nleft join(\nselect \nld_modtracker_basic.crmid,\nmax(ld_modtracker_basic.changedon) as changedon,\nld_modtracker_detail.fieldname,\nld_modtracker_detail.postvalue\nfrom ld_modtracker_basic \nleft join ld_modtracker_detail on ld_modtracker_basic.id=ld_modtracker_detail.id\nwhere ld_modtracker_basic.module=\'Potentials\'\nand ld_modtracker_detail.postvalue=\'成功结案\' \nand ld_modtracker_detail.fieldname=\'sales_stage\'\ngroup by ld_modtracker_basic.crmid\n)modtracker on modtracker.crmid=p.potentialid\nwhere p.sales_stage=\'成功结案\'\n and p.deleted=0 and p.createdtime>=DATE_FORMAT(\'{starttime}\',\'%Y-%m-%d 00:00:00\') and p.createdtime<=DATE_FORMAT(\'{endtime}\',\'%Y-%m-%d 23:59:59\')\nand find_in_set(p.smownerid,\'{userid}\')\n)a group by smownerid\n)a order by smownerid asc,ordernum asc;','yes','no','no',0,1,72,'potiential_report_avg_period',NULL),(125,'商机阶段停留时长统计（按人员）',NULL,'',NULL,'no',NULL,NULL,'yes','2023-03-23 18:32:16','2023-03-27 09:51:03',0,1,1,0,'sql','select \np.smownerid,\np.potential_no,\np.potentialid,\np.potentialname,\na.accountname,\nu.last_name,\np.total,\nmodtracker.prevalue as postvalue,\nmodtracker.createdtime,\nmodtracker.endtime,\ntimestampdiff(HOUR,modtracker.createdtime,modtracker.endtime)as gaptime\nfrom \nld_potential p \nleft join ld_account a on p.accountid=a.accountid\nleft join ld_users u on u.id=p.smownerid\nleft join(\nselect   t.crmid,t1.crmid as crmid1 ,timestampdiff(HOUR,t1.changedon,t.changedon)as gaptime,t1.j,t.prevalue,\ncase when t.crmid<>ifnull(t1.crmid,0)  then t.createdtime else t1.changedon  end as createdtime ,t.changedon as endtime \nfrom \n(select (@i:=@i+1) as i,a.*,p.createdtime,detail.postvalue,detail.prevalue from ld_modtracker_basic  as a left join ld_modtracker_detail detail on  detail.id=a.id INNER JOIN ld_potential  as p on p.potentialid=a.crmid and p.deleted=0 and detail.fieldname=\'sales_stage\' and a.module=\'Potentials\',(select @i:=0) as it    order by id asc) t\nleft join \n(select (@j:=@j+1) as j,a.* from ld_modtracker_basic as a left join ld_modtracker_detail detail on  detail.id=a.id INNER JOIN ld_potential \nas p on p.potentialid=a.crmid and p.deleted=0 and  detail.fieldname=\'sales_stage\' and a.module=\'Potentials\',(select @j:=1) as it     order by id asc ) t1\non t.i=t1.j\n\nunion all \n\nselect\n a.crmid,a.crmid as crmid1,\'-\' as gaptime,0 as j,detail.postvalue,a.changedon as createdtime,\'-\'as endtime\nfrom ld_modtracker_basic  as a left join ld_modtracker_detail detail on  detail.id=a.id\nINNER JOIN (SELECT max(a.id) AS id FROM ld_modtracker_basic a LEFT JOIN ld_modtracker_detail detail ON detail.id = a.id WHERE detail.fieldname = \'sales_stage\' AND a.module = \'Potentials\' GROUP BY crmid )b on a.id=b.id \nwhere detail.fieldname=\'sales_stage\' and a.module=\'Potentials\'\n\n)modtracker on modtracker.crmid=p.potentialid\nwhere p.deleted=0\nand p.createdtime>=DATE_FORMAT(\'{starttime}\',\'%Y-%m-%d 00:00:00\') and p.createdtime<=DATE_FORMAT(\'{endtime}\',\'%Y-%m-%d 23:59:59\')\nand find_in_set(p.smownerid,\'{userid}\')\norder by p.smownerid asc,p.potentialid desc,modtracker.createdtime desc','yes','no','no',0,1,72,'potiential_report_stay_period',NULL),(126,'客户汇总统计表',NULL,'',NULL,'no',NULL,NULL,'yes','2023-03-27 11:22:54','2023-03-27 11:45:06',0,1,1,0,'sql','select \nld_users.last_name,\nld_users.id as userid,\na.accountallnums,\na.accountthisnums,\na.effectivenums,\nb.newsales,\nb.oldsales\nfrom ld_users \nleft join (\nselect \nsum(case when createdtime<=DATE_FORMAT(\'{endtime}\',\'%Y-%m-%d 23:59:59\') then 1 else 0 end ) as accountallnums,\nsum(case when createdtime>=DATE_FORMAT(\'{starttime}\',\'%Y-%m-%d 23:59:59\') and createdtime<=DATE_FORMAT(\'{endtime}\',\'%Y-%m-%d 23:59:59\') then 1 else 0 end ) as accountthisnums,\nsum(case when rating<>\'失败关闭\' then 1 else 0 end) as effectivenums,\nsmownerid\nfrom ld_account \nwhere ld_account.deleted=0 and find_in_set(smownerid,\'{userid}\')\nGROUP BY smownerid\n)a on a.smownerid=ld_users.id\nleft join (\nselect \nsum(case when sales.thisnums=1 and sales.allnums=1 then 1 else 0 end )as newsales,\nsum(case when sales.thisnums>=1 and sales.allnums>=1 then 1 else 0 end )as oldsales,\nld_account.smownerid\n  from ld_account\nleft join (\nselect \nsum(case when createdtime>=DATE_FORMAT(\'{starttime}\',\'%Y-%m-%d 00:00:00\') and createdtime<=DATE_FORMAT(\'{endtime}\',\'%Y-%m-%d 23:59:59\')then 1 else 0 end )as thisnums,\ncount(1)as allnums,\naccountid\nfrom ld_salesorder \nwhere deleted=0 \ngroup by accountid\n)sales on sales.accountid=ld_account.accountid\ngroup by ld_account.smownerid\n)b on b.smownerid=ld_users.id\nwhere ld_users.deleted=0 \nand (a.accountallnums >0 or\na.accountthisnums >0 or\na.effectivenums >0 or\nb.newsales >0 or\nb.oldsales)\nand find_in_set(ld_users.id,\'{userid}\')','yes','no','no',0,1,63,'account_gather_report',NULL);
