INSERT INTO `ld_emailtemplates` VALUES ('Personal','管理体系认证到期通知',NULL,'管理体系认证到期通知','<p style=\"line-height: 3em;\"><span style=\"font-size: 20px; text-decoration: underline; color: rgb(255, 0, 0);\"><strong>尊敬的客户：</strong></span></p><p style=\"line-height: 3em;\"><span style=\"font-size: 14px;\">&nbsp; &nbsp; &nbsp;<strong> &nbsp;<span style=\"font-size: 20px;\"> &nbsp;<span style=\"color: rgb(255, 0, 0);\">您好！您的管理体系认证即将到期，请及时关注电话通知及跟进。</span></span></strong></span></p><p></p><p style=\"line-height: 2em;\"><span style=\"font-size: 14px;\">&nbsp;广东中司控股集团成立于2012年2月，是一家企业一站式服务平台，公司将通过自身优势及资源整合，为企业提供资质认证咨询（ISO9001、ISO14001、ISO45001<span style=\"font-size: 14px; white-space: normal;\">、ISO22000<span style=\"font-size: 14px; white-space: normal;\">、ISO20000<span style=\"font-size: 14px; white-space: normal;\">、ISO27001<span style=\"font-size: 14px; white-space: normal;\">、ISO13485<span style=\"font-size: 14px; white-space: normal;\">、IATF16949等）</span></span></span></span></span>管理咨询辅导、客户验厂辅导（BSCI<span style=\"font-size: 14px; white-space: normal;\">、BRC<span style=\"font-size: 14px; white-space: normal;\">、GSV<span style=\"font-size: 14px; white-space: normal;\">、GRS<span style=\"font-size: 14px; white-space: normal;\">、SEDEX<span style=\"font-size: 14px; white-space: normal;\">、SQP<span style=\"font-size: 14px; white-space: normal;\">、SA8000<span style=\"font-size: 14px; white-space: normal;\">、FSC等）</span></span></span></span></span></span></span>、人才梯队建设（MBA、学历教育）、企业数字化流程建设（灵当CRM管理系统）、企业金融管理等。公司以自己的创新力、预见力、整合力，以精湛的专业水平和高度的责任感倾心企业、回报企业、服务企业，活跃于各行各业，并取得卓越的成效。广东中司控股集团全体同仁将谒诚为您服务，与贵司合作创造更多的企业财富、提升企业竞争力、实现贵司利润最大化是我司的宗旨，期待与您的合作！</span></p><p style=\"line-height: 2em;\"><span style=\"color: rgba(0, 0, 0, 0.9); font-family: Roboto, \" san=\"\" helvetica=\"\" hiragina=\"\" sans=\"\" wenquanyi=\"\" micro=\"\" microsoft=\"\" yahei=\"\" white-space:=\"\" background-color:=\"\" font-size:=\"\"></span></p><p><br/></p><p style=\"line-height: 2em;\"><span style=\"font-size: 14px;\">联系人：<span style=\"font-size: 14px; white-space: normal;\">全国咨询电话：4008558359</span></span></p><p style=\"line-height: 2em;\"><span style=\"font-size: 14px;\">罗老师&nbsp; 13713424686（微信同号）</span></p><p style=\"line-height: 2em;\"><span style=\"font-size: 14px;\">倪老师&nbsp; 13925505059（微信同号）</span></p><p style=\"line-height: 2em;\"><span style=\"font-size: 14px;\"><span style=\"font-size: 14px; white-space: normal;\">沈老师&nbsp;&nbsp;</span><span style=\"font-size: 14px; white-space: normal;\">18681149319（微信同号）</span></span></p><p style=\"line-height: 2em;\"><span style=\"font-size: 14px;\"><span style=\"font-size: 14px; white-space: normal;\">东莞松山湖总部</span>地址：东莞市松山湖林润智谷5栋1103-1105室</span></p><p style=\"line-height: 2em;\"><span style=\"font-size: 14px;\">东莞长安分部<span style=\"font-size: 14px; white-space: normal;\">地址：东莞市长安镇太安路长安段915号8004室</span></span></p><p style=\"line-height: 2em;\"><span style=\"font-size: 14px;\">深圳龙华分部地址：<span style=\"font-size: 14px; white-space: normal;\">深</span></span><span style=\"font-size: 14px;\">圳市龙华区三联社区联汇大厦2层203号</span></p><p style=\"line-height: 2em;\"><span style=\"font-size: 14px;\">公司网站：www.gdzss.cn</span></p>',0,20,1);
