/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `ld_employment` (
  `employment_id` int(11) NOT NULL,
  `employment_no` varchar(100) DEFAULT NULL,
  `smownerid` int(11) NOT NULL,
  `smcreatorid` int(11) DEFAULT NULL,
  `createdtime` datetime DEFAULT NULL,
  `employment_name` varchar(100) DEFAULT NULL,
  `employment_joineddate` date DEFAULT NULL,
  `employment_position` varchar(100) DEFAULT NULL,
  `employment_expirationdate` date DEFAULT NULL,
  `employment_group` text,
  `employment_phone` varchar(30) DEFAULT NULL,
  `employment_salary` decimal(25,8) DEFAULT NULL,
  `employment_idcard` varchar(100) DEFAULT NULL,
  `employment_signing` varchar(100) DEFAULT NULL,
  `employment_state` varchar(100) DEFAULT NULL,
  `employment_residence` text,
  `employment_emergencyname` varchar(100) DEFAULT NULL,
  `employment_emergencycontact` varchar(30) DEFAULT NULL,
  `employment_description` text,
  `modifiedby` int(11) DEFAULT NULL,
  `modifiedtime` datetime DEFAULT NULL,
  `approvestatus` varchar(200) DEFAULT NULL,
  `approvetime` datetime DEFAULT NULL,
  `approveby` int(11) DEFAULT NULL,
  `currentapprover` varchar(1000) DEFAULT NULL,
  `latestpushtime` datetime DEFAULT NULL,
  `advance_stage` varchar(100) DEFAULT NULL,
  `exchtime` datetime DEFAULT NULL,
  `exchmsg` text,
  `team_memberid` text,
  `tag` text,
  `print_times` int(11) DEFAULT NULL,
  `approvesubmitter` int(11) DEFAULT NULL,
  `approvesubmittedtime` datetime DEFAULT NULL,
  `currentapprovestepid` int(19) DEFAULT NULL,
  `approveurgent` varchar(10) DEFAULT NULL,
  `approveexpediting` varchar(10) DEFAULT NULL,
  `kis_id` varchar(200) DEFAULT NULL,
  `kis_no` varchar(100) DEFAULT NULL,
  `deleted` int(4) DEFAULT '0',
  PRIMARY KEY (`employment_id`),
  KEY `createdtime` (`createdtime`),
  KEY `modifiedtime` (`modifiedtime`),
  KEY `deleted` (`deleted`),
  KEY `smownerid` (`smownerid`),
  KEY `smcreatorid` (`smcreatorid`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;
/*!40101 SET character_set_client = @saved_cs_client */;

