r\n项目（身体原因除外） ， 对公司造成损失， 除停止支付所有费用以外。\r\n6、 咨询师在辅导期间对客户任何资料和体系文件、 客户信息绝对保密， 没有书面准许不得向第三方泄露， 违者追究相关人员责任。\r\n7、 未经甲方书面同意， 项目结束五年内， 乙方不得单独到丙方企业任职和咨询企业项目， 乙方（咨询师） 也不得与丙方（企业） 发生咨询辅导业务关系， 如乙方违约,甲方（启龙） 可向乙方提出赔偿。\r\n8、 启龙公司（项目收到款） 每 15 号/30 号给老师结款一次。',100,3,186,1,'V~O',1,100,'BAS',1,NULL,0,0,1,NULL,0,0,NULL,NULL,2,0,'yes','yes','yes','yes','yes',0,0,'yes','longtextarea','all',5,NULL,'yes',NULL,NULL,NULL,'no','#333333','','2023-04-28 03:49:20','2024-09-06 10:59:00','listview',NULL,'no','no',0,'no',NULL,NULL,'no','no','yes',NULL,NULL,'yes','no',NULL,'no','yes','yes','no',NULL,NULL,NULL,NULL,NULL,NULL,NULL),(6,1404,'completed','yes','ld_account',0,'203','completed','公海目标',1,1,NULL,NULL,14,9,2,'V~O',1,NULL,NULL,1,NULL,0,0,1,NULL,0,0,NULL,NULL,2,0,'no','no','no','no','no',0,0,'yes',NULL,'all',5,NULL,'yes',NULL,NULL,NULL,'no',NULL,NULL,'2023-04-28 03:49:20','2024-10-24 05:38:31',NULL,'','no','no',0,'no',NULL,NULL,'no','no','yes',NULL,NULL,'yes','no','no','no','yes','no','no',NULL,NULL,'',NULL,NULL,'{\"color\":\"#333333;\"}',''),(26,1405,'startdate','yes','ld_campaign',1,'5','startdate','预计开始日期',1,2,'thistoday',100,8,74,1,'D~M',0,NULL,'BAS',1,NULL,0,0,1,NULL,0,0,NULL,NULL,2,0,'yes','yes','yes','yes','yes',0,0,'yes','date',NULL,0,NULL,'yes',NULL,NULL,NULL,'no',NULL,NULL,'2023-04-28 03:49:20','2023-09-06 10:14:03','listview',NULL,'no','no',0,'no',NULL,NULL,'no','no','yes',NULL,NULL,'yes','yes',NULL,'no','yes','no','no',NULL,NULL,NULL,NULL,NULL,NULL,NULL),(70,1406,'adjustment','yes','ld_outboundorder',1,'72','txtAdjustment','调整',1,2,NULL,100,16,130,3,'N~O~25,2',0,NULL,'BAS',1,NULL,0,0,1,1,0,0,NULL,NULL,2,0,'no','no','no','no','no',0,0,'yes','currency',NULL,0,NULL,'yes',NULL,NULL,NULL,'no',NULL,NULL,'2023-04-28 03:49:20','2023-12-04 08:37:45',NULL,NULL,'no','no',0,'no',NULL,NULL,'no','no','yes',NULL,NULL,'yes','no','yes','no','yes','no','no',NULL,NULL,NULL,NULL,NULL,NULL,NULL),(64,1407,'entitytypeid','yes','ld_paymentplan',1,'202','entitytypeid','选择源单',1,2,NULL,100,3,121,1,'V~M',0,3,'