\':\'a\',\'column\':\'social_base\'},{\'lettervar\':\'b\',\'column\':\'endowment_rate\'}]}','','2024-05-08 06:29:29','2024-05-08 06:29:29'),(34,8474,'a*b*0.01','{formulavar:[{\'lettervar\':\'a\',\'column\':\'social_base\'},{\'lettervar\':\'b\',\'column\':\'unemployment_rate\'}]}','','2024-05-08 06:29:29','2024-05-08 06:29:29'),(35,8476,'a*b*0.01','{formulavar:[{\'lettervar\':\'a\',\'column\':\'social_base\'},{\'lettervar\':\'b\',\'column\':\'house_rate\'}]}','','2024-05-08 06:29:29','2024-05-08 06:29:29'),(37,8477,'a+b+c+d+e*f*0.01','{formulavar:[{\'lettervar\':\'a\',\'column\':\'endowment_insurance\'},{\'lettervar\':\'b\',\'column\':\'medical_insurance\'},{\'lettervar\':\'c\',\'column\':\'unemployment_insurance\'},{\'lettervar\':\'d\',\'column\':\'injury_insurance\'},{\'lettervar\':\'e\',\'column\':\'house_base\'},{\'lettervar\':\'f\',\'column\':\'house_rate\'}]}','','2024-05-08 06:29:29','2024-05-08 06:29:29'),(38,8440,'a-b-c','{formulavar:[{\'lettervar\':\'a\',\'column\':\'payable_subtotal\'},{\'lettervar\':\'b\',\'column\':\'attendance_subtotal\'},{\'lettervar\':\'c\',\'column\':\'insurance_subtotal\'}]}','','2024-05-08 06:29:29','2024-05-08 06:29:29'),(39,8442,'SELECT\r\n	CASE\r\n		WHEN yingna_total<=0 THEN 0.00\r\n		WHEN yingna_total<36000 THEN ROUND(yingna_total*0.03-yina_total,2)\r\n		WHEN yingna_total<144000 THEN ROUND(yingna_total*0.1-2520-yina_total,2)\r\n		WHEN yingna_total<300000 THEN ROUND(yingna_total*0.2-16920-yina_total,2)\r\n		WHEN yingna_total<420000 THEN ROUND(yingna_total*0.25-31920-yina_total,2)\r\n		WHEN yingna_total<660000 THEN ROUND(yingna_total*0.3-52920-yina_total,2)\r\n		WHEN yingna_total<960000 THEN ROUND(yingna_total*0.35-85920-yina_total,2)\r\n		WHEN yingna_total>=960000 THEN ROUND(yingna_total*0.45-181920-yina_total,2)\r\n	END AS tmp_value\r\nFROM (\r\n	SELECT\r\n		SUM(yingna_total)+\'{c}\'-\'{d}\'-\'{e}\' AS yingna_total,\r\n		SUM(yina_total) AS yina_total\r\n	FROM (\r\n		SELECT\r\n			SUM(IFNULL(pretax_salary_total,0)-IFNULL(insurance_subtotal,0)-IFNULL(additional_subtotal,0)-IFNULL(tax_startpoint,0)) AS yingna_total,\r\n			SUM(IFNULL(individual_income_tax,0)) AS yina_total\r\n		FROM ld_salary\r\n		WHERE deleted=0\r\n			AND approvestatus<>\'已拒绝\'\r\n			AND LEFT(salary_period,4)=LEFT(\'{a}\',4)\r\n			AND RIGHT(salary_period,2)<RIGHT(\'{a}\',2)\r\n			AND smownerid=\'{b}\'\r\n		UNION\r\n		SELECT 0 AS yingna_total,0 AS yina_total\r\n	) a\r\n) a','{formulavar:[{\'lettervar\':\'a\',\'column\':\'salary_period\'},{\'lettervar\':\'b\',\'column\':\'smownerid\'},{\'lettervar\':\'c\',\'column\':\'pretax_salary_total\'},{\'lettervar\':\'d\',\'column\':\'tax_startpoint\'},{\'lettervar\':\'e\',\'column\':\'additional_subtotal\'}]}','sql','2024-05-08 06:29:29','2024-05-08 06:29:29'),(41,4300,'a-b','{formulavar:[{\'lettervar\':\'a\',\'column\':\'cf_4292\'},{\'lettervar\':\'b\',\'column\':\'cf_4299\'}]}','','2024-07-17 02:37:20','2024-07-17 02:37:20'),(42,4299,'a+b+c+d+e+f+g+h','{formulavar:[{\'lettervar\':\'a\',\'column\':\'cf_4293\'},{\'lettervar\':\'b\',\'column\':\'cf_7534\'},{\'lettervar\':\'c\',\'column\':\'cf_7535\'},{\'lettervar\':\'d\',\'column\':\'cf_4295\'},{\'lettervar\':\'e\',\'column\':\'cf_4298\'},{\'lettervar\':\'f\',\'column\':\'cf_4296\'},{\'lettervar\':\'g\',\'column\':\'cf_4297\'},{\'lettervar\':\'h\',\'column\':\'cf_7536\'}]}','','2024-07-17 02:37:33','2024-07-17 02:37:33'),(44,8441,'a-b+c','{formulavar:[{\'lettervar\':\'a\',\'column\':\'pretax_salary_total\'},{\'lettervar\':\'b\',\'column\':\'individual_income_tax\'},{\'lettervar\':\'c\',\'column\':\'otherpayable_subtotal\'}]}','','2024-09-06 10:58:38','2024-09-06 10:58:38'),(45,8684,'SELECT 0+\'{a}\'+\'{b}\'+\'{c}\'+\'{d}\'+\'{e}\'+\'{f}\'+\'{g}\'+\'{h}\'+\'{i}\'+\'{j}\' as tmp_value','{formulavar:[{\'lettervar\':\'a\',\'column\':\'global_awareness\'},{\'lettervar\':\'b\',\'column\':\'collaboration_awareness\'},{\'lettervar\':\'c\',\'column\':\'service_awareness\'},\r\n       {\'lettervar\':\'d\',\'column\':\'communication_ability\'},{\'lettervar\':\'e\',\'column\':\'business_ability\'},{\'lettervar\':\'f\',\'column\':\'planning_ability\'},\r\n       {\'lettervar\':\'g\',\'column\':\'innovation_ability\'},{\'lettervar\':\'h\',\'column\':\'principality\'},{\'lettervar\':\'i\',\'column\':\'responsibility\'},{\'lettervar\':\'j\',\'column\':\'morality\'}]}','sql','2024-09-06 10:58:47','2024-09-06 10:58:47');
