INSERT INTO `ld_mailmanager_mailrecord` VALUES (1,'QQ邮箱团队 <10000@qq.com>','中司认证 <nixiangtian@vip.qq.com>',NULL,NULL,'2023-07-21 15:34:52','更安全、更高效、更强大，尽在QQ邮箱APP','\r\n<!DOCTYPE html>\r\n<html>\r\n<head>\r\n  <meta charset=\"UTF-8\">\r\n  <title>imap</title>\r\n  <style>\r\n    @media screen and (min-width: 700px) {\r\n      .bottomErweima {\r\n        display: block !important;\r\n      }\r\n      #btn {\r\n        display: none !important;\r\n      }\r\n      .footer {\r\n        display: none !important;\r\n      }\r\n    }\r\n    /* vivo手机width: 980px 同时 aspect-ratio小于1的,处于700px-1000px的手机*/\r\n    @media screen and (min-width: 700px) and (max-width: 1000px) and (max-aspect-ratio:1/1){\r\n      .bottomErweima {\r\n        display: none !important;\r\n      }\r\n      #btn {\r\n        display: block !important;\r\n      }\r\n      .footer {\r\n        display: block !important;\r\n      }\r\n    }\r\n  </style>\r\n</head>\r\n<body style=\"width: 100%;margin: 0;padding: 0;position: relative;\">\r\n  <div id=\"email-box\" style=\"max-width: 550px;margin: 0 auto;\">\r\n    <div class=\"email_container\">\r\n      <div  class=\"head\" style=\"background: #f3f3f3;\">\r\n        <span class=\"content\" style=\"font-size: 14px;color: #000000;line-height: 26px;display: block;padding: 40px 20px;\">QQ邮箱APP，让高效触手可及。在这里，你可以登录多个邮箱账号、便捷存储微信邮件、多窗口编辑邮件......还有更多功能，等你探索！</span>\r\n      </div>\r\n       <div class=\"part\" style=\"color: #000000;text-align: center;margin-top: 40px;\">\r\n        <h1 style=\"font-size: 30px; margin: 0;\">01</h1>\r\n        <h2 style=\"font-size: 20px;margin-bottom: 14px;margin-top: 0;\">多帐号登录</h2>\r\n        <p style=\"margin-bottom: 0;font-size: 13px;color: #8E8E93;\">可以同时登录多个邮箱帐号</p>\r\n        <p style=\"margin-top: 5px; font-size: 13px;color: #8E8E93;\">一站式灵活管理各类邮件信息</p>\r\n        <img style=\"width: 100%;\" src=\"https://rescdn.qqmail.com/qqmail/images/manyAccountLoginImg.png\" alt=\"\">\r\n      </div>\r\n      <div class=\"part\" style=\"color: #000000;text-align: center;margin-top: 40px;\">\r\n        <h1 style=\"font-size: 30px; margin: 0;\">02</h1>\r\n        <h2 style=\"font-size: 20px;margin-bottom: 14px;margin-top: 0;\">文件中转站</h2>\r\n        <p style=\"margin-bottom: 0;font-size: 13px;color: #8E8E93;\">把各类文件存在云端</p>\r\n        <p style=\"margin-top: 5px;font-size: 13px;color: #8E8E93;\">还能便捷导入微信文件，过期烦恼不再有</p>\r\n        <img style=\"width: 100%;\" src=\"https://rescdn.qqmail.com/qqmail/images/fileTransferStation.png\" alt=\"\">\r\n      </div>\r\n      \r\n      <div class=\"part\" style=\"color: #000000;text-align: center;margin-top: 40px;\">\r\n        <h1 style=\"font-size: 30px; margin: 0;\">03</h1>\r\n        <h2 style=\"font-size: 20px;margin-bottom: 14px;margin-top: 0;\">多窗口编辑</h2>\r\n        <p style=\"margin-bottom: 0;font-size: 13px;color: #8E8E93;\">写邮件、写记事、写日程都可收起为浮窗</p>\r\n        <p style=\"margin-top: 5px;font-size: 13px;color: #8E8E93;\">编辑内容的同时不错过重要邮件</p>\r\n        <img style=\"width: 100%;\" src=\"https://rescdn.qqmail.com/qqmail/images/edit.png\" alt=\"\">\r\n      </div>\r\n      <div class=\"part\" style=\"color: #000000;text-align: center;margin-top: 40px;\">\r\n        <h1 style=\"font-size: 30px; margin: 0;\">04</h1>\r\n        <h2 style=\"font-size: 20px;margin-bottom: 14px;margin-top: 0;\">富文本信息一键添加</h2>\r\n        <p style=\"margin-bottom: 0;font-size: 13px;color: #8E8E93;\">日程邀请、地理位置、记事本、在线文档</p>\r\n        <p style=\"margin-top: 5px;font-size: 13px;color: #8E8E93;\">这些重要内容可以一键加入邮件正文</p>\r\n        <img style=\"width: 100%;\" src=\"https://rescdn.qqmail.com/qqmail/images/language.png\" alt=\"\">\r\n      </div>\r\n      <div class=\"part\" style=\"color: #000000;text-align: center;margin-top: 40px;\">\r\n        <h1 style=\"font-size: 30px; margin: 0;\">05</h1>\r\n        <h2 style=\"font-size: 20px;margin-bottom: 14px;margin-top: 0;\">灵活管理日程</h2> \r\n        <p style=\"margin-bottom: 0;font-size: 13px;color: #8E8E93;\">全新日历功能、日程列表更清晰，重要事件不错过</p>\r\n        <p style=\"margin-top: 5px;font-size: 13px;color: #8E8E93;\">还可以邀请伙伴共同参与，提升合作效率</p>\r\n        <img style=\"width: 100%;\" src=\"https://rescdn.qqmail.com/qqmail/images/routin.png\" alt=\"\">\r\n      </div>\r\n    </div>\r\n    <div class=\"footer\" style=\"width: 100%;background-image: linear-gradient(180deg, #F6F6F6 0%, #FFFFFF 59%);padding-bottom: 30px;\">\r\n      <p class=\"footer_1\" style=\"font-size: 12px;color: #8E8E93;letter-spacing: 0.92px;text-align: center;padding-top: 30px;padding-bottom: 20px;\">下载全新QQ邮箱App，体验更多特色新功能</p>\r\n      <p class=\" footer_2\" style=\"font-size: 11px;color: #C7C7C7;text-align: center;\">\r\n        —— <img class=\"brand\" style=\"width: 17px;margin-left:5px;margin-right: 5px;vertical-align:middle\" src=\"https://rescdn.qqmail.com/qqmail/images/brand.png\"><span>QQ邮箱 ——</span></p>\r\n    </div>\r\n    <a id=\"btn\" style=\"color: #fff;text-decoration: none;width: 100%;height: 46px;display: block;padding-top: 2px;text-align: center;margin-bottom: 10px;\" href=\"https://wx.mail.qq.com/list/readtemplate?name=proxy.html&type=1&xmuin=13102661337534271\">\r\n      <span class=\"btn-text\" style=\"display: block;background: #177ee6;margin: 0 20px;padding: 11px 0;border-radius: 4px;\">\r\n        立即体验\r\n      </span>\r\n    </a>\r\n    <img class=\"bottomErweima\" style=\"width: 100%;display: none;margin-top: 50px;\" src=\"https://rescdn.qqmail.com/qqmail/images/emailDownloadErweima.png\" alt=\"\">\r\n    <img class=\"countKv\"\r\n    src=\"https://wx.mail.qq.com/info/report?func=4&items=%7B%22itemname%22%3A%22Imap_thirdparty_read_expose%22%2C%22value%22%3A1%2C%22logid%22%3A16292%2C%22xmuin%22%3A13102661337534271%7D\"\r\n    style=\"position:absolute; left:-10000px; top:-10000px;\" />\r\n  </div>\r\n</body>\r\n</body>\r\n</html>\r\n',NULL,NULL,NULL,NULL,'ZC0021_7tHNdrmMNpQudmQAxZr_6d7',1,NULL,NULL,1,0,1,'312659775@qq.com',0,'2023-07-21 15:36:07',NULL,'pop'),(1,'腾讯云 <cloud_noreply@tencent.com>','312659775 <312659775@qq.com>',NULL,NULL,'2023-0