    }\n\n    table {\n        table-layout: fixed;\n        word-break: break-strict;\n        border-collapse: collapse;\n    }\n\n    th {\n        font-weight: normal;\n    }\n\n    .iconfont {\n        display: none;\n    }\n\n    pre {\n        white-space: pre-wrap;\n        white-space: -moz-pre-wrap;\n        white-space: -pre-wrap;\n        white-space: -o-pre-wrap;\n        font-family: Microsoft YaHei, 微软雅黑, 宋体;\n    }\n\n    a {\n        color: #666;\n        text-decoration: unset;\n    }\n\n    .pb15 {\n        padding-bottom: 10px;\n    }\n\n    body {\n        /*line-height: 22px;*/\n        font-family: Microsoft YaHei, 微软雅黑, 宋体;\n        background: #fff;\n        font-size: 14px;\n        margin: 0;\n        padding: 0;\n    }\n\n\n    .borderb {\n        border-bottom: 1px solid #e8e8e8;\n    }\n\n    .text-overflow {\n        overflow: hidden;\n        text-overflow: ellipsis;\n        white-space: nowrap;\n    }\n\n    .cgray {\n        color: #999999;\n    }\n\n    .cblue {\n        color: #1d4abc;\n    }\n\n    .cblack {\n        color: #222222;\n    }\n\n    .cut {\n        color: #999999;\n    }\n\n    /*放table里进行排版*/\n    table {\n        /*width: 100%;*/\n        table-layout: auto;\n        color: #222222;\n        font-size: 16px;\n    }\n\n    table tr, table td {\n        padding: 0;\n    }\n\n    /*整体*/\n    .main-table {\n        margin: 0 auto;\n        /*width: 820px;*/\n    }\n\n\n    /* ---------- 顶部 begin ---------- */\n    .top-info {\n\n    }\n\n    .top-info-box {\n        position: relative;\n    }\n    .top-info-box .logo-img {\n\n    }\n\n    .top-info-box .other-info {\n        color: #222222;\n        /*position: absolute;*/\n        /*right: 0;*/\n        /*top: 15px;*/\n        max-width: 220px;\n        font-size: 12px;\n    }\n\n    .top-info .other-info div {\n        margin-top: 5px;\n        line-height: 18px;\n    }\n\n    .top-info .other-info div:first-child {\n        margin-top: 0;\n    }\n\n    /* ---------- 顶部 end ---------- */\n\n    /* ---------- 头像 基本信息 begin ---------- */\n    .user-info {\n        /*margin-top: 30px;*/\n    }\n\n    .avatar-div .portrait {\n        border: #F8FAFF solid 1px;\n        width: 120px;\n        height: 120px;\n        border-radius: 4px;\n    }\n\n    /*隐藏头像*/\n    .avatar-div .hideAvatar {\n        display: block;\n        position: relative;\n    }\n\n    .avatar-div .hideAvatar:after {\n        position: absolute;\n        bottom: 0;\n        left: 0;\n        width: 100%;\n        border-radius: 15px;\n        content: \"隐藏头像\";\n        height: 22px;\n        line-height: 22px;\n        background: #1d4abc;\n        color: white;\n        text-align: center;\n        font-size: 14px;\n    }\n\n    .user-info-td {\n\n    }\n\n    .user-info-td .user-name {\n        font-size: 26px;\n        color: #141414;\n        padding-right: 10px;\n        font-weight: bold;\n        white-space: nowrap;\n    }\n\n    .user-info-td .deal-type-span {\n        color: #1D4ABC;\n        border: #1D4ABC 1px solid;\n        border-radius: 2rem;\n        font-size: 12px;\n        padding: 1px 8px 2px;\n        position: relative;\n        bottom: 2px;\n    }\n\n    .user-info-td .last-online-date {\n        padding-left: 8px;\n        white-space: inherit;\n    }\n\n    .user-info-td .job-state-str {\n        text-align: right;\n        color: #1D4ABC;\n        font-size: 16px;\n        /*font-weight: bold;*/\n        /*white-space: nowrap;*/\n    }\n\n    .small-tips {\n        font-size: 12px;\n        color: #999999;\n    }\n\n    .user-info-td.contact-div > div {\n        color: #222222;\n        font-size: 16px;\n    }\n\n    /* ---------- 头像 基本信息 end ---------- */\n\n    .dashed {\n        border-bottom: 1px dashed #e8e8e8;\n        border-top: 0;\n    }\n\n    /* ---------- 各个part的信息 begin ---------- */\n\n    .infoBlock {\n        /*margin-top: 25px;*/\n    }\n\n\n    .infoBlock .info-block-title {\n        font-size: 20px;\n        color: 