play: inline-block;\n        text-align: center;\n        border-radius: 18px;\n        padding: 2px 10px;\n        font-size: 12px;\n        white-space: nowrap;\n\n        background-color: #EEF4FF;\n        border: none !important;\n        color: #333;\n    }\n\n    .infoBlock .time-td {\n        /*width: 40%;*/\n        white-space: nowrap;\n        text-align: right;\n        color: #999999;\n        font-size: 12px;\n    }\n\n\n    .infoBlock .enclosure a {\n        text-decoration: underline;\n    }\n\n    .infoBlock.skills .skill-item {\n        margin-top: 4px;\n    }\n\n    .infoBlock.skills .skill-item:first-child {\n        margin-top: 0;\n    }\n\n</style>\n </head>  \n <body> \n  <img src=\"https://img.job5156.com/img/email?imgKey=8097766732058423404&amp;maskCode=53d11bc1fcd02fc208e336a44a55e34e&amp;imgTo=\" alt=\"\" width=\"1\" height=\"1\" style=\"display: none\">\n  <table width=\"720\" class=\"main-table\" border=\"0\" cellspacing=\"0\" style=\"background:  url(\'https://hr.job5156.com/api/image/getWatermark/1990161\')  0 646px repeat rgb(255, 255, 255);\" align=\"center\" cellpadding=\"0\"> \n   <tbody>\n    <tr>  \n     <td height=\"10\" colspan=\"2\" valign=\"bottom\"> <img src=\"https://hr.job5156.com/public/images/export/head.jpg\" style=\"float: left\" width=\"720\" height=\"10\"> </td> \n    </tr> \n    <tr> \n     <td colspan=\"2\"> \n      <table width=\"720\"> \n       <tbody>\n        <tr> \n         <td valign=\"top\" width=\"550\"> <img src=\"https://hr.job5156.com/public/images/export/logo.png\" style=\"float: left\" width=\"305\" height=\"46\"> </td> \n         <td> <p style=\"text-align: left; width: 200px; font-size: 12px;line-height: 1.5\">简历编号：180643938<br> 应聘职位：品质经理（ISO16949体系咨询师）<br> 投递时间：2023-07-19 10:49</p> <p style=\"line-height: 8px; font-size: 8px\">&nbsp;</p> </td> \n        </tr> \n       </tbody>\n      </table> </td> \n    </tr> \n    <tr> \n     <td rowspan=\"2\" width=\"50\">&nbsp;</td> \n     <td> \n      <table width=\"670\" style=\"margin-top: 10px\"> \n       <tbody>\n        <tr> \n         <td valign=\"top\" width=\"160\"> \n          <div class=\"avatar-div\"> \n           <a class=\"\" style=\"margin-right: 25px; float: left\"> <img class=\"portrait \" width=\"140\" height=\"140\" style=\"float: left;\" src=\"https://pub.job5156.com/winopen/2022/images/hyy-nan50514.png\"> </a> \n          </div> </td> \n         <td style=\"font-size: 14px\" valign=\"bottom\"> <strong style=\"font-size: 28px; font-weight: bold\">邓文锋</strong> <span style=\"color: #194EC2\">&nbsp;&nbsp;目前正在找工作 1个月内到岗</span><br> 18820348871 <span class=\"small-tips\"> （该号码归属地：广东 东莞） </span> <br>wfdeng8888@126.com </td>\n        </tr> \n       </tbody>\n      </table> </td> \n    </tr> \n    <tr> \n     <td> <br> <p style=\"font-size: 13px\">简历链接：<a href=\"https://hr.job5156.com/resume/view/1771019\" class=\"cblue\" target=\"_blank\">https://hr.job5156.com/resume/view/1771019</a> </p> <br> <p style=\"font-size: 16px; font-weight: bold; color: #000; line-height: 1;  vertical-align: bottom;\"><img src=\"https://hr.job5156.com/public/images/export/title.png\">&nbsp;&nbsp;基本信息</p> <p style=\"line-height: 8px; font-size: 8px\">&nbsp;</p> <p style=\"font-size: 12px; color: #666; text-indent: 10px; \"> 男 <span class=\"cut\">&nbsp;|&nbsp;</span> 53岁 <span class=\"cut\">&nbsp;|&nbsp;</span> 已婚 <span class=\"cut\">&nbsp;|&nbsp;</span> 本科 <span class=\"cut\">&nbsp;|&nbsp;</span> 10年以上经验 <span class=\"cut\">&nbsp;|&nbsp;</span> 广东 <span class=\"cut\">&nbsp;|&nbsp;</span> 165cm <span class=\"cut\">&nbsp;|&nbsp;</span> 汉 <span class=\"cut\">&nbsp;|&nbsp;</span> 湖南 </p> <p>&nbsp;</p> <p style=\"font-size: 16px; font-weight: bold; color: #000; line-height: 1;  vertical-align: bottom;\"><img src=\"https://hr.job5156.com/public/images/export/title.png\">&nbsp;&nbsp;求职意向</p> <p style=\"line-height: 8px; font-size: 8px\">&nbsp;</p> <p style=\"font-size: 14px; text-indent: 10px; color: #000000;\">工程经理/主管</p> <p style=\"font-size: 12px; text-indent: 10px; color: #666666;\"> 10000-14999元/月<span class=\"cut\">&nbsp;|&nbsp;</span>广东<span class=\"cut\">&nbsp;|&nbsp;</span>全职 </p> <p>&nbsp;</p> <p style=\"font-size: 14px; text-indent: 10px; color: #000000;\">部门/事业部经理/主管</p> <p style=\"font-size: 12px; text-indent: 10px; color: #666666;\"> 10000-14999元/月<span class=\"cut\">&nbsp;|&nbsp;</span>广东<span class=\"cut\">&nbsp;|&nbsp;</span>全职 </p> <p>&nbsp;</p> <p style=\"font-size: 14px; text-indent: 10px; color: #000000;\">其它高级管理类</p> <p style=\"font-size: 12px; text-indent: 10px; color: #666666;\"> 10000-14999元/月<span class=\"cut\">&nbsp;|&nbsp;</span>广东<span class=\"cut\">&nbsp;|&nbsp;</span>全职 </p> <p>&nbsp;</p> <p style=\"font-size: 16px; font-weight: bold; color: #000; line-height: 1;  vertical-align: bottom;\"><img src=\"https://hr.job5156.com/public/images/export/title.png\">&nbsp;&nbsp;个人优势</p> <p style=\"line-height: 8px; font-size: 8px\">&nbsp;</p> <p style=\"line-height: 4px; font-size: 4px\">&nbsp;</p> <pre style=\"font-size: 12px; color: #333;white-space: pre-wrap; word-wrap: break-word;line-height: 20px; margin-left: 10px;\">自我评价：1,本人91年毕业，至今已有15年的工作经验，从事过制造工程技术，大中型企业管理和人才培训工作。 \n2,特别对制造工厂的现场管理，改善及制造技术和IE工程有特别强的经验。爱好体育，音乐，看书看报等。 \n3,参加过国内外多家知名度的企业培训。 \n4、善于沟通，能进行相关资源整合和供应商开发、管理。 \n5、谦虚好学，敢于创新，踏实肯干，极富团队精神。 \n6、熟悉 OEM 业务操作流程、规律和产品完善跟进工作。 \n7、熟悉相关产品的法律、法规。 \n8、具有ISO9001/ISO14001内审员资格，熟悉并参与QMS和EMS运作 \n9、熟悉新产品研发、管理流程，拥有大量的第一手管理资料和心得。 \n10、具有ISO9001/ISO14001内审员资格，熟悉并参与QMS和EMS运作。 \n11、方正科技计算机集团公司技术管理学院特聘讲师。\n\n职业技能：语  言  能  力：  普通话流利,粤语一般 \n英语水平：  CET-4 \n英语口语：  熟练 \n第一外语：  英语 精通 第二外语：  日语 一般 \n计 算 机 能 力：  高级 \n计算机详细技能：  能熟练熟练使用各种办公软件和专业软件,能编写一般的程序 \n其  它  技  能：  10年从事产品制造工程、质量工程和生产制造经验。且在体系,培训,技术,管理等方面有较强的经验.能熟练地使用各种专用软件.</pre> <p>&nbsp;</p> <p style=\"font-size: 16px; font-weight: bold; color: #000; line-height: 1;  vertical-align: bottom;\"><img src=\"https://hr.job5156.com/public/images/export/title.png\">&nbsp;&nbsp;工作经历</p> <p style=\"line-height: 8px; font-size: 8px\">&nbsp;</p> <p style=\"font-size: 14px; color: #222; margin-left:10px;\"> 雀巢饮料自动售货设备有限公司<span class=\"cut\">&nbsp;|&nbsp;</span> <span style=\"font-size: 12px; color: #666; text-indent: 10px; \">质量技术中心总监兼总经理助理</span><span class=\"cut\">&nbsp;|&nbsp;</span> <span class=\"time-td\" style=\"font-size: 12px; color: #999;\">2009-08~2021-02 （11年6月） </span> </p> <p class=\"cgray\" style=\"font-size: 12px; color: #999; line-height: 2; margin-left:10px;\"> 行业：生产/制造/加工 <span class=\"cut\">&nbsp;|&nbsp;</span>性质：外资企业 <span class=\"cut\">&nbsp;|&nbsp;</span>规模：500-1000 </p> <p style=\"line-height: 5px; font-size: 5px\">&nbsp;</p> \n      <div style=\"margin-left:10px;\"> \n       <pre style=\"font-size: 12px; color: #333;white-space: pre-wrap; word-wrap: break-word;line-height: 20px;\">1 ,全面负责公司产品质量控制和生产工程的设计、开发；\n2 ,负责质量部门及工程部门工作的整体运作,工作计划和展开；\n3 ,客户需求分析、产品规划、工业造型设计、结构设计、五金件、注塑件和模具设计跟进（开模、试模、改模）；\n4、熟练使用AUTOCAD、PRO/E、项目管理软件：PROJECT2002。办公软件：OFFICE、\n5、负责过产品的设计试验、噪声设计、电磁兼容设计试验和产品认证申请操作，熟悉电子产品EMC从前端设计开发到认证申请的全过程和环节。设计过的多款产品均已通过3C、UL、PSE、SAA等认证；\n6、熟悉OEM/ODM业务的相关法律法规、工作流程、团队开发管理、资源整合、项目规划管理。熟悉产品跟进，擅长产品缺陷分析、塑胶、五金模具的修模和产品完善；\n7、精通产品设计流程和项目管理（项目评审--可行性分析--立项--设计任务书--推进计划--ID--3D图纸--3D打印--首板验证--开模--跟模--模具验证--样品验证----实验验证--试产--量产等等）\n\n8、全面负责产品质量部门工作的统筹和实施\nA、建立各部门、各岗位工作质量目标，并转换为绩效考核的指标，参与公司年度生产计划、质量计划、绩效考核机制及实施管理办法等的策划，并定期跟进和监督；\nB、编制并审核产品质量标准；同时参与并评审新产品或新项目开发,评审,设计的验证；\n----对新产品或常规产品进行实验验证；\nC、定期或不定期地对供应商进行评审，包括供应商质量管控、供应商技术能力评估、产能及质量改善等；同时对其质量体系的执行状况进行全面的监督和评价；\nD、对进料检验方法与控制（IQC），制程检验方法与控制（IPQC），成品检验方法与控制（FQC）等进行策划和监督；\nE、负责客户投诉工作，针对客户投诉组织相关部门进行原因分析、提出有效措施并用8D报告回复客户，直到客户满意；\nF、对生产或其他过程产生的不合格品进行控制，并推动相关部门进行纠正预防措施；\nD、参与公司国军标和ISO体系的文件编制和审核；\n\n9、,同时全面负责生产工程工作：\nA，完善作业流程及生产车间的布置,作业指导书,工艺流程,排拉,人\n员安排等\nB，制程不良，来料不良及客户投诉分析和改善。\nC,SMT,AI,波峰焊等重要工艺的设计改善及新`机种编程.\nD,生产线设备（包括SMT,AI,波峰焊）治具等的维护保养.\nE，新产品试产及新部品试作和相关过程分析。\nF，进行定期和不定期可靠性试验工作和各种安规的认证和测试。\nG，定期对供应商进行品质监察和考核，评估。\nH，利用FMEA，MTBF等工具进行可靠性试验失效模式分析及各种实验分析。\n11 ,负责新产品或新项目开发,评审,设计；\n12 ,负责公司的现场改善和节源提效工作；\n13、 ,编制部门的年度计划；\n14 ,产品改良和新产品试产；\n15,负责公司所有设备的的维护和安装、调试、保养工作.\n16,公司供电系统、供气系统、供水系统的维护.\n17，具有丰富的团体组建与扩充经验和项目管理与协调经验.\n18,擅长项目的计划,预算控制,资源统筹,质量控制与进度管理</pre> \n      </div> <p>&nbsp;</p> <p style=\"font-size: 14px; color: #222; margin-left:10px;\"> 艾雷斯科技有限公司<span class=\"cut\">&nbsp;|&nbsp;</span> <span style=\"font-size: 12px; color: #666; text-indent: 10px; \">工程部总监</span><span class=\"cut\">&nbsp;|&nbsp;</span> <span class=\"time-td\" style=\"font-size: 12px; color: #999;\">2004-8~2009-08 （5年） </span> </p> <p class=\"cgray\" style=\"font-size: 12px; color: #999; line-height: 2; margin-left:10px;\"> 行业：生产/制造/加工 <span class=\"cut\">&nbsp;|&nbsp;</span>性质：私营·民营企业 </p> <p style=\"line-height: 5px; font-size: 5px\">&nbsp;</p> \n      <div style=\"margin-left:10px;\"> \n       <pre style=\"font-size: 12px; color: #333;white-space: pre-wrap; word-wrap: break-word;line-height: 20px;\">1 ,全面负责公司产品的工业工程和生产工程的设计、规划和 \n策略; \n2 ,负责工工程设计部门工作的整体运作,工作计划和展开; \n3 ,参与公司国军标和ISO体系的文件编制和审核; \n4,负责本部门具体工作的管理和实施： \nA，完善作业流程及生产车间的布置,作业指导书,工艺流程,排拉,人 \n员安排等 \nB，制程不良，来料不良及客户投诉分析和改善。 \nC,SMT,AI,波峰焊等重要工艺的设计改善及新`机种编程. \nD,生产线设备(包括SMT,AI,波峰焊)治具等的维护保养. \nE，新产品试产及新部品试作和相关过程分析。 \nF，进行定期和不定期可靠性试验工作和各种安规的认证和测试。 \nG，定期对供应商进行品质监察和考核，评估。 \nH，利用FMEA，MTBF等工具进行可靠性试验失效模式分析及各种实验分析。 \n\n5 ,负责新产品或新项目开发,评审,设计; \n6 ,负责公司的现场改善和节源提效工作; \n7 ,编制部门的年度计划; \n8 ,产品改良和新产品试产; \n9 ,负责产品和部件的评测工作. \n10,负责公司所有设备的的维护和安装、调试、保养工作. \n11,公司供电系统、供气系统、供水系统的维护. \n12，具有丰富的团体组建与扩充经验和项目管理与协调经验. \n13,擅长项目的计划,预算控制,资源统筹,质量控制与进度管理</pre> \n      </div> <p>&nbsp;</p> <p style=\"font-size: 14px; color: #222; margin-left:10px;\"> 东莞市方正电脑科技有限公司<span class=\"cut\">&nbsp;|&nbsp;</span> <span style=\"font-size: 12px; color: #666; text-indent: 10px; \">品质工程部经理</span><span class=\"cut\">&nbsp;|&nbsp;</span> <span class=\"time-td\" style=\"font-size: 12px; color: #999;\">2000-8~2004-2 （3年6月） </span> </p> <p class=\"cgray\" style=\"font-size: 12px; color: #999; line-height: 2; margin-left:10px;\"> 行业：生产/制造/加工 <span class=\"cut\">&nbsp;|&nbsp;</span>性质：股份制企业 </p> <p style=\"line-height: 5px; font-size: 5px\">&nbsp;</p> \n      <div style=\"margin-left:10px;\"> \n       <pre style=\"font-size: 12px; color: #333;white-space: pre-wrap; word-wrap: break-word;line-height: 20px;\">1，负责本部门日常工作的开展并实施监督和考核。 \n2，配合公司整体发展战略，制定并实施本部门工作的季度和度计划， 品质计划和目标。 \n3，优化业务流程推动ISO体系的有效运行. \n4，具备组织能力，管理能力，协调能力，沟通能力和技术技巧能力等。 \n5，负责本部门具体工作的管理和实施： \nA，完善作业流程及生产车间的布置。 \nB，制程不良，来料不良及客户投诉分析和改善。 \nC，新产品试产及新部品试作和相关过程分析。 \nD，仪器仪表的调校和鉴定。 \nE，负责公司ISO体系工作的申请和认证，编制体系文件，完善体系流程。 \nF，品质管制工具，SPC等品质技术的培训与应用。 \nG，进行定期和不定期可靠性试验工作和各种安规的认证和测试。 \nH，定期对供应商进行品质监察和考核，评估。 \nI ，负责整个公司的技术和管理的培训工作。 \nJ ，利用FMEA，MTBF等工具进行可靠性试验失效模式分析及各种实验分析。 \n6，参与重大品质事故的分析处理和改善。</pre> \n      </div> <p>&nbsp;</p> <p style=\"font-size: 14px; color: #222; margin-left:10px;\"> 惠州SONY索尼精密部件有限公司<span class=\"cut\">&nbsp;|&nbsp;</span> <span style=\"font-size: 12px; color: #666; text-indent: 10px; \">制造技术课长</span><span class=\"cut\">&nbsp;|&nbsp;</span> <span class=\"time-td\" style=\"font-size: 12px; color: #999;\">1996-8~2000-2 （3年6月） </span> </p> <p class=\"cgray\" style=\"font-size: 12px; color: #999; line-height: 2; margin-left:10px;\"> 行业：生产/制造/加工 <span class=\"cut\">&nbsp;|&nbsp;</span>性质：上市公司 </p> <p style=\"line-height: 5px; font-size: 5px\">&nbsp;</p> \n      <div style=\"margin-left:10px;\"> \n       <pre style=\"font-size: 12px; color: #333;white-space: pre-wrap; word-wrap: break-word;line-height: 20px;\">1，编制工艺流程，作业指导书，排拉，人员安排，流水线平蘅。 \n2，设备的相关分析，数据处理，工艺制程能力指数分析。 \n3，制程不良分析，客户投诉事件的处理。 \n4，利用FMEA，MTBF等工具进行可靠性试验失效模式分析及各种实验分析。 \n5，进行可靠性试验测试和安规测试。 \n6，新产品试产和新部品试作。 \n7，制作各种测试用夹治具及限度样品。 \n8，检验标准和检验规范的制的制作，客户不良和来料不良分析。 \n9，编制文件，参与内审及负责公司的培训工作。 \n10，拟定和发行PCN，ECN等产品制造变更和设计变更等。 \n11，优化业务流程推动ISO体系的有效运行。 \n12，参与公司的现场改善活动，QCC活动等。 \n13，制程能力分析。</pre> \n      </div> <p>&nbsp;</p> <p style=\"font-size: 14px; color: #222; margin-left:10px;\"> 深圳沙井德昌电机有限公司<span class=\"cut\">&nbsp;|&nbsp;</span> <span style=\"font-size: 12px; color: #666; text-indent: 10px; \">PIE工程师</span><span class=\"cut\">&nbsp;|&nbsp;</span> <span class=\"time-td\" style=\"font-size: 12px; color: #999;\">1993-3~1995-11 （2年8月） </span> </p> <p class=\"cgray\" style=\"font-size: 12px; color: #999; line-height: 2; margin-left:10px;\"> 行业：生产/制造/加工 <span class=\"cut\">&nbsp;|&nbsp;</span>性质：港资企业 </p> <p style=\"line-height: 5px; font-size: 5px\">&nbsp;</p> \n      <div style=\"margin-left:10px;\"> \n       <pre style=\"font-size: 12px; color: #333;white-space: pre-wrap; word-wrap: break-word;line-height: 20px;\">1，从事产品的结构设计,外形设计,制程中的夹具、治具设计。 \n\n2，编制作业指导书，工序手册，PCN，ECN。制定标准工时，排拉，流水线平蘅。 \n3，厂房布置和物流的畅通。 \n4，制作各种测试用夹治具及限度样品。 \n5，工程不良分析，工艺改善。 \n6，客诉事件的处理。 \n7，新产品试产和部品试作，制程能力分析。 \n8，参与公司的现场改善活动，QCC活动等。 \n9，利用FMEA，MTBF等工具进行可靠性试验失效模式分析及各种 \n实验分析。 \n10，公司电气电路的维修，厂房宿舍的安装维修等工作。</pre> \n      </div> <p>&nbsp;</p> <p style=\"font-size: 14px; color: #222; margin-left:10px;\"> 常宁市第一中学<span class=\"cut\">&nbsp;|&nbsp;</span> <span style=\"font-size: 12px; color: #666; text-indent: 10px; \">教师</span><span class=\"cut\">&nbsp;|&nbsp;</span> <span class=\"time-td\" style=\"font-size: 12px; color: #999;\">1991-9~1992-12 （1年3月） </span> </p> <p class=\"cgray\" style=\"font-size: 12px; color: #999; line-height: 2; margin-left:10px;\"> 行业：教育/培训/科研院所 <span class=\"cut\">&nbsp;|&nbsp;</span>性质：事业单位 </p> <p style=\"line-height: 5px; font-size: 5px\">&nbsp;</p> \n      <div style=\"margin-left:10px;\"> \n       <pre style=\"font-size: 12px; color: #333;white-space: pre-wrap; word-wrap: break-word;line-height: 20px;\">担任过高一，高三物理教学，高三数学教学 \n曾经获得市教育战线优秀教师称号</pre> \n      </div> <p>&nbsp;</p> <p style=\"font-size: 16px; font-weight: bold; color: #000; line-height: 1;  vertical-align: bottom;\"><img src=\"https://hr.job5156.com/public/images/export/title.png\">&nbsp;&nbsp;教育经历</p> <p style=\"line-height: 8px; font-size: 8px\">&nbsp;</p> \n      <table cellspacing=\"0\" border=\"0\" width=\"610\" style=\"margin-left: 10px\"> \n       <tbody>\n        <tr> \n         <td> <p class=\"main-text\" style=\"font-size: 14px; color: #222;\"> 华南理工大学 <span style=\"font-size: 12px; color: #666; text-indent: 10px; \"> <span class=\"cut\">&nbsp;|&nbsp;</span>大专<span class=\"cut\">&nbsp;|&nbsp;</span>电子技术应用 </span> </p> </td> \n         <td align=\"right\" class=\"time-td\" style=\"font-size: 12px; color: #999; text-align: right;width: 180px\"> 2003-9~2005-6 </td> \n        </tr> \n       </tbody>\n      </table> \n      <table cellspacing=\"0\" border=\"0\" width=\"610\" style=\"margin-left: 10px\"> \n       <tbody>\n        <tr> \n         <td> <p class=\"main-text\" style=\"font-size: 14px; color: #222;\"> 衡阳师范学院 <span style=\"font-size: 12px; color: #666; text-indent: 10px; \"> <span class=\"cut\">&nbsp;|&nbsp;</span>本科<span class=\"cut\">&nbsp;|&nbsp;</span>物理 </span> </p> </td> \n         <td align=\"right\" class=\"time-td\" style=\"font-size: 12px; color: #999; text-align: right;width: 180px\"> 1988-9~1991-7 </td> \n        </tr> \n       </tbody>\n      </table> <p>&nbsp;</p> <p style=\"font-size: 16px; font-weight: bold; color: #000; line-height: 1;  vertical-align: bottom;\"><img src=\"https://hr.job5156.com/public/images/export/title.png\">&nbsp;&nbsp;培训经历</p> <p style=\"line-height: 8px; font-size: 8px\">&nbsp;</p> \n      <table cellspacing=\"0\" border=\"0\" width=\"610\" style=\"margin-left: 10px\"> \n       <tbody>\n        <tr> \n         <td> <p class=\"main-text\" style=\"font-size: 14px; color: #222;\"> 零缺陷管理与现代企业管理 <span style=\"font-size: 12px; color: #666; text-indent: 10px; \"> <span class=\"cut\">&nbsp;|&nbsp;</span> 北京克劳斯比管理学院 </span> </p> </td> \n         <td align=\"right\" class=\"time-td\" style=\"font-size: 12px; color: #999; text-align: right;\"> 2004-12 ~2005-1 （1月） </td> \n        </tr> \n        <tr> \n         <td>&nbsp;</td> \n         <td style=\"width: 180px; height: 40px\">&nbsp;</td> \n        </tr> \n        <tr> \n         <td> <p class=\"main-text\" style=\"font-size: 14px; color: #222;\"> 电磁兼容性 <span style=\"font-size: 12px; color: #666; text-indent: 10px; \"> <span class=\"cut\">&nbsp;|&nbsp;</span> 中国电子认证中心 </span> </p> </td> \n         <td align=\"right\" class=\"time-td\" style=\"font-size: 12px; color: #999; text-align: right;\"> 2003-11 ~2004-1 （2月） </td> \n        </tr> \n        <tr> \n         <td>&nbsp;</td> \n         <td style=\"width: 180px; height: 40px\">&nbsp;</td> \n        </tr> \n       </tbody>\n      </table> <p>&nbsp;</p> <p style=\"font-size: 16px; font-weight: bold; color: #000; line-height: 1;  vertical-align: bottom;\"><img src=\"https://hr.job5156.com/public/images/export/title.png\">&nbsp;&nbsp;技能特长</p> <p style=\"line-height: 8px; font-size: 8px\">&nbsp;</p> <p style=\"font-size: 12px; color: #666; text-indent: 10px;  text-indent:0px\"> </p><p style=\"line-height: 8px; font-size: 8px\">&nbsp;</p> <span class=\"skill-item\" style=\"line-height: 28px;\">英语 <span class=\"cut\">&nbsp;|&nbsp;</span>熟练 </span> <br> <span class=\"skill-item\" style=\"line-height: 28px;\">英语 <span class=\"cut\">&nbsp;|&nbsp;</span>大学英语等级考试CET-4 </span> <br> <p></p> <p>&nbsp;</p> </td> \n    </tr> \n   </tbody>\n  </table>   \n </body>\n</html>\n',NULL,NULL,NULL,NULL,'ZC0019_pZrNDMOMO5kudmQAT1NGLd7',1,NULL,NULL,1,0,11,'312659775@qq.com',0,'2023-07-21 15:36:14',NULL,'pop'),(1,'智通人才网 <service@srv8.job5156.com>','312659775@qq.com <312659775@qq.com>',NULL,NULL,'2023-07-19 09:46:54','智通人才网-【王=-utf-8-B-5bm05Y2O44CR5bqU6IGY44CQ5ZOB6LSo57uP-==-utf-8-B-55CG77yISVNPMTY5NDnkvZPns7vlkqjor6LluIjvvInjgJE=-=',NULL,NULL,NULL,NULL,NULL,'ZC0019_YV7NA8yMO5kudmQAL8kFId7',NULL,NULL,NULL,0,0,12,'312659775@qq.com',0,'2023-07-21 15:36:15',NULL,'pop'),(1,'智通人才网 <service@srv8.job5156.com>','312659775@qq.com <312659775@qq.com>',NULL,NULL,'2023-07-19 00:10:14','智通人才网-【卿=-utf-8-B-5paw5piO44CR5bqU6IGY44CQ5ZOB6LSo57uP-==-utf-8-B-55CG77yISVNPMTY5NDnkvZPns7vlkqjor6LluIjvvInjgJE=-=',NULL,NULL,NULL,NULL,NULL,'ZC0019_mabN~jWMOpgudmQA17~Gyd7',NULL,NULL,NULL,0,0,13,'312659775@qq.com',0,'2023-07-21 15:36:15',NULL,'pop'),(1,'Apple <noreply@icloud.com.cn>','312659775@qq.com',NULL,NULL,'2023-07-18 22:50:37','你的_