ted = 0 AND leadsid = ?','no'),(42,142,4,0,0,0,3,116,'all',NULL,5,0,0,1,'yes',NULL,NULL,'yes',0.0000,NULL,'no',0,NULL,NULL,NULL,'yes',NULL,NULL,'sql','SELECT CONCAT(IFNULL(ld_account.bill_state,\"\"),IFNULL(ld_account.bill_city,\"\"),IFNULL(ld_account.bill_area,\"\"),ld_account.bill_street) AS tmp_value FROM ld_contactdetails INNER JOIN ld_account ON ld_account.accountid = ld_contactdetails.accountid WHERE ld_account.deleted = 0 AND ld_contactdetails.contactid = {Record.ID}','no'),(43,142,55,0,0,0,4,116,'all',NULL,5,0,0,1,'yes',NULL,NULL,'yes',0.0000,NULL,'no',0,NULL,NULL,NULL,'yes',NULL,NULL,'sql','SELECT CONCAT(IFNULL(ld_account.bill_state,\"\"),IFNULL(ld_account.bill_city,\"\"),IFNULL(ld_account.bill_area,\"\"),ld_account.bill_street) AS tmp_value FROM ld_contactrecords INNER JOIN ld_account ON ld_account.accountid = ld_contactrecords.accountid WHERE ld_account.deleted = 0 AND ld_contactrecords.contactrecordID = {Record.ID}','no'),(44,142,2,0,0,0,5,116,'all',NULL,5,0,0,1,'yes',NULL,NULL,'yes',0.0000,NULL,'no',0,NULL,NULL,NULL,'yes',NULL,NULL,'sql','SELECT CONCAT(IFNULL(ld_account.bill_state,\"\"),IFNULL(ld_account.bill_city,\"\"),IFNULL(ld_account.bill_area,\"\"),ld_account.bill_street) AS tmp_value FROM ld_potential INNER JOIN ld_account ON ld_account.accountid = ld_potential.accountid WHERE ld_account.deleted = 0 AND ld_potential.potentialid = {Record.ID}','no'),(45,142,48,0,0,0,7,116,'permit',NULL,5,0,0,1,'yes',NULL,NULL,'yes',0.0000,NULL,'no',0,NULL,NULL,NULL,'yes',NULL,NULL,'sql','SELECT CONCAT(IFNULL(ld_account.bill_state,\"\"),IFNULL(ld_account.bill_city,\"\"),IFNULL(ld_account.bill_area,\"\"),ld_account.bill_street) AS tmp_value FROM ld_project INNER JOIN ld_account ON ld_account.accountid = ld_project.accountid WHERE ld_account.deleted = 0 AND ld_project.projectid = {Record.ID}','no'),(46,142,14,1,0,0,9,116,'all',NULL,5,0,0,1,'yes',NULL,NULL,'yes',0.0000,NULL,'no',0,NULL,NULL,NULL,'yes',NULL,NULL,'sql','SELECT CONCAT(\r\n					IF(LOCATE(IFNULL(ld_account.