INSERT INTO `ld_organizationdetails_brief` VALUES (28,1,'广东中司控股集团有限公司是一家综合性咨询服务机构。是专业从事管理培训、管理咨询、体系认证（ISO9001、ISO14001、IATF16949、SA8000、GB/T50430、ISO45001、HACCP、ISO22000、CCC产品强制性认证、海关认证、服务体系认证、反恐体系认证、各类客户验厂培训指导）等咨询业务的服务机构。','','text'),(29,1,'公司以自己的创新力、预见力、整合力，以精湛的专业水平和高度的责任感倾心企业、回报企业、服务企业，活跃于电子、五金、塑胶、机械、纸品、印刷、食品、鞋业、制衣、玩具、化工、物业、养殖、酒店、物流、建筑、房地产、政府服务机构等各行各业，并取得卓越的成效。','','text'),(30,1,'广东中司控股集团有限公司全体同仁将谒诚为您服务，与贵司合作创造更多的企业财富、提升企业竞争力、实现贵司利润最大化是我司的宗旨，期待与您的合作！','','text'),(31,1,'◆使   命：中之大业，司创企新。\r\n  让中小企业管理变的简单，企业改革创新是中司成立的使命。\r\n◆愿   景：成为行业内受人尊敬的管理专家团队。\r\n  广东中司的管理专家团队将经过不断的学习、创新，始终坚持初心来服务企业。','','text'),(32,1,'◆定   位：为中小企业提供科学先进的管理咨询服务。\r\n             广东中司成立之初已将公司定位为中小企业管理咨询服务提供商，公司将通过不断的探索、研究、实践，建立一套符合中国公司并可落地的先进管理理念，并不断优化，去旧推新。\r\n◆价值观：以人为本，诚信咨询；服务企业，幸福自我。\r\n 广东中司采用合伙人制度，处处彰显以人为本的管理理念，并通过诚信服务企业，让客户、让公司\r\n 员工在工作中感受幸福的人生价值。','','text');
/*!40000 ALTER TABLE `ld_organizationdetails_brief` ENABLE KEYS */;
UNLOCK TABLES;

