DROP TABLE IF EXISTS `ld_picklist_values`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `ld_picklist_values` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `listid` int(11) DEFAULT NULL,
  `listvalue` varchar(200) DEFAULT NULL,
  `sequence` int(11) DEFAULT NULL,
  `scores` decimal(25,2) DEFAULT NULL,
  `weight` decimal(25,2) DEFAULT NULL,
  `utrc_type` varchar(100) DEFAULT NULL,
  `subjectcode` varchar(100) DEFAULT NULL,
  `subjectsummary` varchar(200) DEFAULT NULL,
  `pick_color` varchar(10) DEFAULT NULL,
  `win_rate` int(10) DEFAULT '0',
  `map_module` text,
  `listkey` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `picklist_values_listid` (`listid`) USING BTREE,
  KEY `picklist_values_sequence` (`sequence`) USING BTREE,
  KEY `listvalue` (`listvalue`)
) ENGINE=InnoDB AUTO_INCREMENT=25427 DEFAULT CHARSET=utf8;
/*!40101 SET character_set_client = @saved_cs_client */;

