CREATE  PROCEDURE `add_shareusers`(
	tmp_relatedid int(10)
)
BEGIN
	
          	DECLARE str1 VARCHAR(100);
  					DECLARE str2 VARCHAR(100) default '';
						declare str5 VARCHAR(100) default '';
  					DECLARE done1  int  default 1;
  					DECLARE done2  int  default 1;
	declare var_userid VARCHAR(100);
	
	declare done  int  default 0;
	declare cur1 CURSOR FOR select customform54id from ld_customform54 where accountid=tmp_relatedid;
	declare cur2 CURSOR FOR select viewuserid from ld_tabshare where crmid=tmp_relatedid;
  declare continue handler  for not  found  SET done =1;
	open cur1;
	Fetch cur1 into var_userid;
	loop1: while  done<>1 DO
						set str5=var_userid;
						open cur2;
						Fetch cur2 into str1;
						loop2: while  done<>1 DO
							set str2=str1;
								INSERT INTO ld_tabshare(crmid,viewuserid,Shareuserid,createdtime,viewuserremark)
   								SELECT var_userid,str1,1,NOW(),'自动共享证书' FROM DUAL
   								WHERE NOT EXISTS (SELECT 1 FROM ld_tabshare WHERE crmid=var_userid AND Shareuserid=str1);
							Fetch cur2 into str1;
						end while loop2;
						close cur2;
						set done = 0;
				Fetch cur1 into var_userid;
				Fetch cur1 into var_userid;
	end while loop1;

	close cur1;
end ;;
DELIMITER ;
