CREATE  PROCEDURE `ldcrm_reset_contacts_nolinkdays`(
)
BEGIN
	SET @disable_triggers=1;
	UPDATE ld_contactdetails SET nolinkdays=DATEDIFF(CURDATE(),IFNULL(lastcontactdate,DATE_FORMAT(createdtime,'%Y-%m-%d')));
	UPDATE ld_contactdetails SET xiangshi_days=DATEDIFF(CURDATE(),IFNULL(renshi_date,DATE_FORMAT(createdtime,'%Y-%m-%d')));
	SET @disable_triggers=NULL;
end ;;
